import {GameControllerEvents, GameUtils, Module} from "@silverfoxgames/slotcore";
import {injectFromBase} from "inversify";
import {GameMode, GameSpecificData} from 'src/gamedata/GameSpecificData';
import {RoadView} from 'src/modules/road/RoadView';
import {RoadEvents} from 'src/modules/road/RoadEvents';
import {DifficultyButtonEvents} from 'src/modules/difficulty/DifficultyButtonEvents';

@injectFromBase()
export class RoadModule extends Module<RoadView, GameSpecificData> {
    public restore(): void {
        super.restore();

        this.resetCoinMultipliers(this.gameData.currentGameMode);

        this.view.restoreToPosition(this.gameData.currentStep + 1);
        this.view.restoreBarriersTill(this.gameData.currentStep + 1);

    }

    public resetCoinMultipliers(gameMode: GameMode): void {
        this.view.resetCoinMultipliers(this.gameData.multipliers[gameMode]);
    }

    public restoreCoins(): void {
        this.view.restoreCoins();
    }

    public makeStep(): void {
        this.view.moveLanesOneStep();
    }

    public resetRound(): void {
        this.view.resetRound();
    }

    public spawnFatalCar(laneIndex: number): void {
        this.view.spawnFatalCar(laneIndex)
    }

    public spawnWinBarrier(laneIndex: number): void {
        this.view.playWinCollectCoinAt(laneIndex);

        // this.view.spawnBarrier(laneIndex);
        if (GameUtils.randomInt(1, 10) > 7) {
            this.view.spawnBarrierCar(laneIndex);
        }
    }

    public spawnLoseBarrier(laneIndex: number): void {
        this.view.playLoseCollectCoinAt(laneIndex);
    }

    protected setupEvents(): void {
        super.setupEvents();

        this.onViewEmitEvent(RoadView.FATAL_CAR_REACHED_CHICKEN, RoadEvents.FATAL_CAR_REACHED_CHICKEN);
        this.on(DifficultyButtonEvents.DIFFICULTY_BUTTON_CLICKED, this.onDifficultyChanged);
        this.on(GameControllerEvents.INIT_RECEIVED, this.onInitReceived);

    }

    protected onInitReceived(): void {
        this.resetCoinMultipliers(GameMode.EASY);
    }

    protected onDifficultyChanged(event: string, gameMode: GameMode): void {
        this.resetCoinMultipliers(gameMode);
    }
}