import {MathUtils, Module} from "@silverfoxgames/slotcore";
import {injectFromBase} from "inversify";
import {GameSpecificData} from 'src/gamedata/GameSpecificData';
import {ChickenView} from 'src/modules/chicken/ChickenView';
import {ChickenEvents} from 'src/modules/chicken/ChickenEvents';

@injectFromBase()
export class ChickenModule extends Module<ChickenView, GameSpecificData> {

    public showMultiplier(value: number): void {
        this.view.showCurrentMultiplier();
        this.view.setMultiplierValue(MathUtils.toFixedNumber(value, 2));
    }

    public hideCurrentMultiplier(): void {
        this.view.hideCurrentMultiplier();
    }

    public async makeFirstStep(): Promise<void> {
        // await this.view.makeFirstStep();
        this.emit(ChickenEvents.FIRST_STEP_STARTED);
        this.emit(ChickenEvents.STEP_STARTED);
        await this.view.makeStep();
    }

    public async makeStep(): Promise<void> {
        await this.view.makeStep();
        this.emit(ChickenEvents.STEP_STARTED);
    }

    public resetRound(): void {
        this.view.resetRound();
    }

    public async playDead(): Promise<void> {
        await this.view.playDead();
    }
}