import {GlobalStateIdle} from 'src/modules/globalstate/states/GlobalStateIdle';
import {GameGlobalEvents} from 'src/modules/globalstate/GameGlobalEvents';
import {GameAutoplayHandlerEvents} from 'src/autoplay/GameAutoplayHandlerEvents';
import {CashoutButtonEvents} from 'src/modules/movingUI/cashout/CashoutButtonEvents';
import {GameBasicResponse} from 'src/gamedata/GameSpecificData';
import {GlobalStateSpinModule} from 'src/modules/globalstate/GlobalStateSpinModule';

export class GlobalStateStepIdle extends GlobalStateIdle {

    public onEnterState(): void {
        this.emit(GameGlobalEvents.CHICKEN_STEP_FINISHED);

        this._keypadController.enableOnStepFinished();
        this._cashoutButtonModule.showButton();
    }


    protected setupEvents(): void {
        super.setupEvents();

        this.on(CashoutButtonEvents.CASHOUT_BUTTON_CLICKED, this.onCashOutPressed);
        this.on(GameAutoplayHandlerEvents.AUTOPLAY_CASHOUT, this.onCashOutPressed)

    }

    protected async onCashOutPressed(): Promise<void> {
        await this.chickenGameController.payout((result: GameBasicResponse) => {
            this.gameData.reactOnCashOut(result);
        });

        this.module.gotoState(GlobalStateSpinModule.WIN);
    }
}