import {injectFromBase} from 'inversify';
import {
    AutoplayButtonModule,
    AutoplayHandlerEvents,
    BasicView,
    BetButtonModule,
    LockReasons,
    Module,
    PlatformEvents,
    RestoreScreenEvents
} from '@silverfoxgames/slotcore';
import {GoButtonModule} from 'src/modules/movingUI/go/GoButtonModule';
import {DifficultyButtonModule} from 'src/modules/difficulty/DifficultyButtonModule';

const KeypadButtons = {
    autoPlayButton: 'autoPlayButton',
    betButton: 'betButton',
    goButton: 'goButton',
    difficultyButton: 'difficultyButton',
};
type ButtonModules = BetButtonModule | AutoplayButtonModule | GoButtonModule | DifficultyButtonModule;
type ButtonNames = keyof typeof KeypadButtons;
export type LockProperties = {
    hide: boolean;
    disable: boolean;
};
export type UnlockProperties = {
    show: boolean;
    enable: boolean;
};
export type KeypadButtonConfig = {
    buttonName: ButtonNames;
    lockProperties?: LockProperties;
    unlockProperties?: UnlockProperties;
};

export const goButtonLockReasons = ['LockReasons::STEP_STARTED', 'LockReasons::AUTOPLAY_STARTED', 'LockReasons::LOCKED_BY_REPLAY'];

export const chickenBetButtonLockReasons = [...goButtonLockReasons, 'LockReasons::BET_FROZEN', 'LockReasons::ROUND_STARTED']

export const chickenAutoplayButtonLockReasons = [...goButtonLockReasons, 'LockReasons::LOCKED_BY_REGULATION', 'LockReasons::ROUND_STARTED'];

export const gameModeButtonLockReasons = [...goButtonLockReasons, 'LockReasons::ROUND_STARTED']

@injectFromBase()
export class ChickenKeypadController extends Module {
    protected _keypad: Record<string, ButtonModules> = {};
    protected _buttonLockingReasons: Record<string, LockReasons[]> = {};

    public init(view: BasicView, viewScreenName?: string): void {
        super.init(view, viewScreenName);

        this.setupKeypadItems();
        this.setupButtonsLockingReasons()
    }

    protected setupEvents(): void {
        super.setupEvents();

        this.on(AutoplayHandlerEvents.AUTOPLAY_STARTED, this.onAutoplayStarted);
        this.on(AutoplayHandlerEvents.AUTOPLAY_STOPPED, this.onAutoplayStopped);

        this.on(PlatformEvents.FREEZE_BET_CALLBACK_CALLED, this.onFreezeBetCalled); // TODO never called for now
        this.on(PlatformEvents.UNFREEZE_BET_CALLBACK_CALLED, this.onUnfreezeBetCalled); // TODO never called for now

        this.on(RestoreScreenEvents.RESTORE_CLOSED, this.onRestoreClosed);
    }

    protected onRestoreClosed(): void {
        this.disableOnRoundStarted();
    }

    protected onAutoplayStarted(): void {
        this.lockWithReason('LockReasons::AUTOPLAY_STARTED');
    }

    protected onAutoplayStopped(): void {
        this.unlockWithReason('LockReasons::AUTOPLAY_STARTED');
    }

    protected onFreezeBetCalled(): void {
        this.lockWithReason('LockReasons::BET_FROZEN');
    }

    protected onUnfreezeBetCalled(): void {
        this.unlockWithReason('LockReasons::BET_FROZEN');
    }

    protected setupKeypadItems(): void {
        this._keypad[KeypadButtons.autoPlayButton] = this.diContainer.get(AutoplayButtonModule);
        this._keypad[KeypadButtons.betButton] = this.diContainer.get(BetButtonModule);
        this._keypad[KeypadButtons.goButton] = this.diContainer.get(GoButtonModule);
        this._keypad[KeypadButtons.difficultyButton] = this.diContainer.get(DifficultyButtonModule);
    }

    protected setupButtonsLockingReasons(): void {
        this._buttonLockingReasons[KeypadButtons.autoPlayButton] = this.getAutoplayButtonLockingReasons();
        this._buttonLockingReasons[KeypadButtons.betButton] = this.getBetButtonLockingReasons();
        this._buttonLockingReasons[KeypadButtons.goButton] = this.getGoButtonLockingReasons();
        this._buttonLockingReasons[KeypadButtons.difficultyButton] = this.getDifficultyButtonLockingReasons();
    }

    /**
     * We can DISABLE each button separately by configure it with KeypadButtonConfig, or we can set the same
     * behaviour for every button: hide: true, disable: true
     */
    protected lockWithReason(reason: LockReasons, config?: KeypadButtonConfig[] | LockProperties): void {
        if (config instanceof Array) {
            config.forEach((key: KeypadButtonConfig) => {
                if (this._keypad[key.buttonName] && this.isValidLockingReasonForButton(key.buttonName, reason)) {
                    this._keypad[key.buttonName].lockWithReason(reason, key.lockProperties ?
                        key.lockProperties : {
                            hide: true,
                            disable: true,
                        });
                }
            });
        } else {
            for (const key in this._keypad) {
                const button = this._keypad[key];

                if (this.isValidLockingReasonForButton(key, reason)) {
                    button.lockWithReason(reason, config ? config : {
                        hide: true,
                        disable: true,
                    });
                }
            }
        }
    }

    /**
     * We can ENABLE each button separately by configure it with KeypadButtonConfig, or we can use default
     * behaviour for every button: show: true, enable: true
     */
    protected unlockWithReason(reason: LockReasons, config?: KeypadButtonConfig[]): void {
        if (config instanceof Array) {
            config.forEach((key: KeypadButtonConfig) => {
                if (this._keypad[key.buttonName] && this.isValidLockingReasonForButton(key.buttonName, reason)) {
                    this._keypad[key.buttonName].unlockWithReason(reason, key.unlockProperties
                        ? key.unlockProperties : {
                            show: true,
                            enable: true,
                        });
                }
            });
        } else {
            for (const key in this._keypad) {
                const button = this._keypad[key];

                if (this.isValidLockingReasonForButton(key, reason)) {
                    button.unlockWithReason(reason, config ? config : {
                        show: true,
                        enable: true,
                    });
                }
            }
        }
    }

    protected isValidLockingReasonForButton(buttonName: string, reason: LockReasons): boolean {
        return this._buttonLockingReasons[buttonName].includes(reason);
    }

    /**
     * Some buttons should not be blocked for each reason, below we will define these rules for each button
     * ovveride if needed to slice unnecessary reason
     */
    protected getBetButtonLockingReasons(): LockReasons[] {
        return chickenBetButtonLockReasons;
    }

    protected getAutoplayButtonLockingReasons(): LockReasons[] {
        return chickenAutoplayButtonLockReasons;
    }

    protected getGoButtonLockingReasons(): LockReasons[] {
        return goButtonLockReasons;
    }

    protected getDifficultyButtonLockingReasons(): LockReasons[] {
        return gameModeButtonLockReasons;
    }

    public disableOnRoundStarted(config?: KeypadButtonConfig[]): void {
        this.lockWithReason('LockReasons::ROUND_STARTED', config);
    }

    public enableOnRoundFinished(config?: KeypadButtonConfig[]): void {
        this.unlockWithReason('LockReasons::ROUND_STARTED', config);
    }

    public disableOnStepStarted(config?: KeypadButtonConfig[]): void {
        this.lockWithReason('LockReasons::STEP_STARTED', config);
    }

    public enableOnStepFinished(config?: KeypadButtonConfig[]): void {
        this.unlockWithReason('LockReasons::STEP_STARTED', config);
    }
}