import {GlobalStateSpinModule} from 'src/modules/globalstate/GlobalStateSpinModule';
import {
	AnimationPlayerModule,
	AnimationPlayerView,
	AutoplayButtonModule,
	AutoplayButtonView,
	AutoplayHandlerModule,
	AutoplayStopButtonModule,
	AutoplayStopButtonView,
	BackgroundModule,
	BackgroundView,
	BetButtonModule,
	BetButtonView,
	BetSvelteMenuModule,
	BigWinModule,
	BigWinView,
	CheatModule,
	ChickenAutoplayMenuSvelteModule,
	CoreDI,
	Game,
	MenuModule,
	QuickPlayButtonModule,
	QuickPlayButtonView,
	RestoreScreenModule,
	RestoreScreenView,
	SystemMessagesModule,
	SystemMessagesView,
	WinAmountPresentationModule,
	WinAmountPresentationView,
} from '@silverfoxgames/slotcore';
import {BasicSlotGame} from 'src/BasicSlotGame';
import {RoadModule} from 'src/modules/road/RoadModule';
import {RoadView} from 'src/modules/road/RoadView';
import {ChickenView} from 'src/modules/chicken/ChickenView';
import {ChickenModule} from 'src/modules/chicken/ChickenModule';
import {CashoutButtonModule} from 'src/modules/movingUI/cashout/CashoutButtonModule';
import {CashoutButtonView} from 'src/modules/movingUI/cashout/CashoutButtonView';
import {ChickenKeypadController} from 'src/keypadController/ChickenKeypadController';
import {GoButtonModule} from 'src/modules/movingUI/go/GoButtonModule';
import {GoButtonView} from 'src/modules/movingUI/go/GoButtonView';
import {GameHUDModule} from 'src/hud/GameHUDModule';
import {GameHUDView} from 'src/hud/GameHUDView';
import {GameSoundController} from 'src/sounds/GameSoundController';
import {LosePresentationModule} from 'src/modules/losepresentation/LosePresentationModule';
import {LosePresentationView} from 'src/modules/losepresentation/LosePresentationView';
import {GameAutoplayHandlerModule} from 'src/autoplay/GameAutoplayHandlerModule';
import {DifficultyButtonModule} from 'src/modules/difficulty/DifficultyButtonModule';
import {DifficultyButtonView} from 'src/modules/difficulty/DifficultyButtonView';

window.addEventListener('DOMContentLoaded', () => {
	// eslint-disable-next-line no-new
	const game = new BasicSlotGame();
	game.diContainer
		.bind<Game>(CoreDI.Game)
		.toConstantValue(game);
	gameReady(game);
});

async function gameReady(game: Game): Promise<void> {
	await game.init();

	await game.loadResources();
	game.addModules(
		{module: GlobalStateSpinModule},
		{module: SystemMessagesModule, view: SystemMessagesView, viewScreen: 'SYSTEM_MESSAGE'},
		{module: AnimationPlayerModule, view: AnimationPlayerView},
		{module: GameHUDModule, view: GameHUDView},
		{module: BackgroundModule, view: BackgroundView, viewScreen: 'BACKGROUND'},
		{module: GoButtonModule, view: GoButtonView, viewScreen: 'GO_BUTTON'},
		{module: CashoutButtonModule, view: CashoutButtonView, viewScreen: 'CASHOUT_BUTTON'},
		{module: BetButtonModule, view: BetButtonView, viewScreen: 'BET_BUTTON'},
		{module: BetSvelteMenuModule},
		{module: ChickenAutoplayMenuSvelteModule},
		{module: AutoplayButtonModule, view: AutoplayButtonView, viewScreen: 'AUTOPLAY_BUTTON'},
		{module: AutoplayStopButtonModule, view: AutoplayStopButtonView, viewScreen: 'AUTOPLAY_STOP_BUTTON'},
		{module: MenuModule},
		{module: GameSoundController},
		{module: ChickenKeypadController},
		{module: QuickPlayButtonModule, view: QuickPlayButtonView, viewScreen: 'QUICKPLAY_BUTTON'},
		{module: WinAmountPresentationModule, view: WinAmountPresentationView, viewScreen: 'WIN_PRESENTATION'},
		{module: LosePresentationModule, view: LosePresentationView, viewScreen: 'WIN_SYMBOLS'},
		{module: BigWinModule, view: BigWinView, viewScreen: 'BIG_WIN'},
		{module: CheatModule},
		{module: GameAutoplayHandlerModule},
		{module: RestoreScreenModule, view: RestoreScreenView, viewScreen: 'SYSTEM_MESSAGE'},
		{module: RoadModule, view: RoadView, viewScreen: 'LANES'},
		{module: ChickenModule, view: ChickenView, viewScreen: 'CHICKEN'},
		{module: DifficultyButtonModule, view: DifficultyButtonView, viewScreen: 'DIFFICULTY_BUTTON'},
	);

	game.onReady();
	game.initModules();
}
