import {
    AtlasNumbers,
    BasicView,
    GameUtils,
    ISpineAnimation,
    MathUtils,
    SCREEN_HEIGHT,
    ScreenOrientation,
    ScreenParams,
    Tween,
    TweenPresetUtils,
} from "@silverfoxgames/slotcore";
import {injectFromBase} from "inversify";
import {Container} from 'pixi.js';

@injectFromBase()
export class RoadView extends BasicView {

    public static readonly CAR_SKINS: string[] = ['BLACK', 'GREEN', 'RED'];

    public static readonly FATAL_CAR_REACHED_CHICKEN: string = 'RoadView::FATAL_CAR_REACHED_CHICKEN';

    // range for the random delay (ms) between car spawns
    private static readonly CAR_SPAWN_MIN_DELAY: number = 1000;
    private static readonly CAR_SPAWN_MAX_DELAY: number = 4000;

    // how long (ms) a car takes to drive from the top to the bottom of the screen
    private static readonly CAR_DRIVE_DURATION: number = 1000;

    // how far (px, in lane-local space) a car should travel past the bottom edge
    // before being destroyed, so it fully clears the screen instead of popping out at the edge
    private static readonly CAR_OFFSCREEN_BUFFER: number = 400;

    // duration (ms) of the tween that shifts the lanes left by one road width
    private static readonly LANE_SHIFT_DURATION: number = 500;

    private static readonly LANE_HEIGHT: number = 10000;


    private _roadMainContainer: Container<any>;
    private _barriersContainer: Container<any>;

    // lane-local y where the top of the screen is (a car becomes visible here)
    private _laneTopY: number = 0;
    // lane-local y where a car has fully driven past the bottom of the screen
    private _laneBottomY: number = 0;

    private _roadElements: Container<any>[] = [];
    private _coins: ISpineAnimation[] = [];
    private _coinValues: AtlasNumbers[] = [];

    // index (into _roadElements) of the lane currently centered under the character
    private _currentOffset: number = 0;
    private _roadWidth: number = 0;
    private _totalLanes: number = 0;

    // angular width of a single lane, as seen from the shared apex point (radians)
    private _laneAngle: number = 0;

    private _cars: ISpineAnimation[] = [];
    private _barriers: ISpineAnimation[] = [];

    public async init(): Promise<void> {
        super.init();

        (window as any).RoadView = this;
        this._totalLanes = this.getConfigValue('game.totalRoads');
        this._roadWidth = this.getConfigValue('game.roadWidth');

        this._roadMainContainer = new Container();
        this._roadMainContainer.position.set(0, -9000);
        this.container.addChild(this._roadMainContainer);

        this._barriersContainer = new Container();
        this._barriersContainer.position.set(0, -9000);
        this.container.addChild(this._barriersContainer);

        // distance from the apex (vanishing point) down to a lane's local y = 0 is just
        // the apex's offset above the screen; every lane shares this same apex, so this
        // maps lane-local y directly to on-screen position along its own centerline
        const apexOffsetY = Math.abs(this._roadMainContainer.position.y);
        const apexDistance = apexOffsetY + SCREEN_HEIGHT;
        this._laneAngle = Math.atan(this._roadWidth / apexDistance) * 1.072;

        this._laneTopY = apexOffsetY - SCREEN_HEIGHT / 2 - RoadView.CAR_OFFSCREEN_BUFFER;
        this._laneBottomY = apexOffsetY + SCREEN_HEIGHT / 2 + RoadView.CAR_OFFSCREEN_BUFFER;

        this.createStartLane();
        for (let i = 0; i < this._totalLanes; i++) {
            this._roadElements.push(this.createLane(i, `${1 + i % 5}`));
        }
        this.createFinishLane(this._totalLanes);


        this._currentOffset = 0;
        this._roadMainContainer.rotation = -this._currentOffset * this._laneAngle;

        void this.spawnCarsLoop();
    }

    public resetCoinMultipliers(values: number[]): void {
        for (let i = 0; i < values.length; i++) {
            const value = values[i];
            this._coinValues[i].showNumber(`x${MathUtils.toFixedNumber(value, 2)}`);
        }
    }

    public restoreCoins(): void {
        for (const coin of this._coins) {
            coin.play('IDLE', 0, true);
        }
    }

    public playWinCollectCoinAt(position: number): void {
        this._coinValues[position].showNumber('');
        this._coins[position].play('MOVE_COLLECT', 0, false, 'COLLECT_IDLE');
    }

    public playLoseCollectCoinAt(position: number): void {
        this._coinValues[position].showNumber('');
        this._coins[position].play('MOVE_DEATH', 0, false, 'DEATH_IDLE');
    }

    public restoreToPosition(laneIndex: number): void {
        this._currentOffset = laneIndex;
        this._roadMainContainer.rotation = this._currentOffset * this._laneAngle;
        this._barriersContainer.rotation = this._currentOffset * this._laneAngle;
    }

    public restoreBarriersTill(laneIndex: number): void {
        for (let i = 0; i < laneIndex; i++) {
            this._coinValues[i].showNumber('');
            this._coins[i].play('COLLECT_IDLE', 0, true);
        }
    }

    public async spawnBarrierCar(laneIndex: number): Promise<void> {
        const lane = this._roadElements[laneIndex];
        const car = this.createCar(lane);
        this._cars.push(car);

        const carOffsetY = this.mainUI.layout.getPosition('CARS', ScreenOrientation.PORTRAIT).y;

        const finalPositionY = RoadView.LANE_HEIGHT - SCREEN_HEIGHT / 2 + carOffsetY;

        await TweenPresetUtils.targetTween(car.spine, {x: 0, y: finalPositionY}, this.updateManager, RoadView.CAR_DRIVE_DURATION)[0].getPromise();
        car.play('STOP', 0, false, 'STOPPED_IDLE');
    }

    public spawnFatalCar(laneIndex: number): void {
        const lane = this._roadElements[laneIndex];
        const car = this.createCar(lane);
        const fatalPositionY = this._laneTopY + (this._laneBottomY - this._laneTopY) / 2

        let shouldCheckFatal = true;
        TweenPresetUtils.targetTween(car.spine, {x: 0, y: this._laneBottomY}, this.updateManager, RoadView.CAR_DRIVE_DURATION)[0]
            .onUpdate( () => {
                if (car.spine.y > fatalPositionY && shouldCheckFatal) {
                    shouldCheckFatal = false;
                    this.emit(RoadView.FATAL_CAR_REACHED_CHICKEN);
                }
            })
            .getPromise()
            .then(() => this.spineUtils.stopAndDestroyAnimation(car));
    }

    public resetRound(): void {
        this._currentOffset = 0;
        this._roadMainContainer.rotation = this._currentOffset * this._laneAngle;

        for (const car of this._cars) {
            this.spineUtils.stopAndDestroyAnimation(car);
        }

        for (const barrier of this._barriers) {
            this.spineUtils.stopAndDestroyAnimation(barrier);
        }

        this._cars = [];
        this._barriers = [];
    }

    public moveLanesOneStep(): void {
        this._currentOffset++;
        this.tweenToCurrentOffset();
    }

    private tweenToCurrentOffset(): void {
        const tween = new Tween(this._roadMainContainer)
            .to({rotation: this._currentOffset * this._laneAngle}, RoadView.LANE_SHIFT_DURATION)
            .start();
        this.updateManager.add(tween);

        const barrierTween = new Tween(this._barriersContainer)
            .to({rotation: this._currentOffset * this._laneAngle}, RoadView.LANE_SHIFT_DURATION)
            .start();
        this.updateManager.add(barrierTween);
    }

    private spawnCarsLoop(): void {
        this.timeUtils.createTimer(() => {
            this.spawnCarRandom();
            this.spawnCarsLoop();
        }, GameUtils.randomInt(RoadView.CAR_SPAWN_MIN_DELAY, RoadView.CAR_SPAWN_MAX_DELAY));
    }

    private spawnCarRandom(): void {
        const laneIndex = Math.min(GameUtils.randomInt(this._currentOffset + 1, this._currentOffset + 4), this._totalLanes - 1);
        const lane = this._roadElements[laneIndex];
        const car = this.createCar(lane);

        TweenPresetUtils.targetTween(car.spine, {x: 0, y: this._laneBottomY}, this.updateManager, RoadView.CAR_DRIVE_DURATION)[0]
            .getPromise()
            .then(() => this.spineUtils.stopAndDestroyAnimation(car));
    }

    private createCar(parentLane: Container<any>): ISpineAnimation {

        return this.spineUtils.startSpineAnimationCreation('CAR.json', 'DRIVING', true)
            .position(0, this._laneTopY)
            .skinName(RoadView.CAR_SKINS[GameUtils.randomInt(0, RoadView.CAR_SKINS.length - 1)])
            .container(parentLane)
            .createAndStart();
    }

    private createLane(index: number, skinName: string, hasCoin: boolean = true): Container<any> {
        const laneContainer = new Container();
        const lane = this.spineUtils.startSpineAnimationCreation('LANES.json', 'IDLE', true)
            .skinName(skinName)
            .position(0, RoadView.LANE_HEIGHT - 1920/2)
            .container(laneContainer)
            .createAndStart();
        // every lane wedge shares the apex at local (0, 0); rotating it around that
        // shared point (instead of offsetting it in x) keeps the taper correct
        laneContainer.rotation = (index * this._laneAngle) * -1;
        this._roadMainContainer.addChild(laneContainer);

        if (hasCoin) {
            const coinYOffset = this.mainUI.layout.getPosition('COINS', ScreenOrientation.PORTRAIT).y;
            const coin = this.spineUtils.startSpineAnimationCreation('COIN_BARRIER.json', 'IDLE', true)
                .position(0, RoadView.LANE_HEIGHT - SCREEN_HEIGHT / 2 + coinYOffset)
                .container(laneContainer)
                .createAndStart();

            const coinValue: AtlasNumbers = new AtlasNumbers(this.assets, 'WINS_');
            coin.spine.addChild(coinValue);
            coinValue.numberKerning = -20;
            coinValue.showNumber(`${index + 1}`);

            this._coins.push(coin);
            this._coinValues.push(coinValue);
        }
        return laneContainer;
    }

    private createStartLane(): Container<any> {
        const laneContainer = new Container();
        this.spineUtils.startSpineAnimationCreation('BCKGR_START.json', 'IDLE', true)
            .position(0, RoadView.LANE_HEIGHT - 1920/2)
            .container(laneContainer)
            .createAndStart();
        laneContainer.rotation = (-1 * this._laneAngle) * -1;
        this._roadMainContainer.addChild(laneContainer);

        return laneContainer;
    }

    private createFinishLane(totalPositions: number): Container<any> {
        const laneContainer = new Container();
        this.spineUtils.startSpineAnimationCreation('BCKGR_FINISH.json', 'IDLE', true)
            .position(0, RoadView.LANE_HEIGHT - 1920/2)
            .container(laneContainer)
            .createAndStart();
        laneContainer.rotation = (totalPositions * this._laneAngle) * -1;
        this._roadMainContainer.addChild(laneContainer);

        return laneContainer;
    }


    public onResized(screenParams: ScreenParams): void {
        super.onResized(screenParams);
/*
        if (screenParams.isPortrait) {
            this._roadMainContainer.position.set(SCREEN_MIN_SIZE / 2 - this._roadWidth / 2, -9000);
        } else {
            this._roadMainContainer.position.set(HALF_SCREEN_WIDTH - this._roadWidth / 2, -9000);
        }*/

    }
}