import {HUDView, GenericButton, ISpineAnimation, AtlasNumbers} from '@silverfoxgames/slotcore';
import {injectFromBase} from 'inversify';
import {Text, TextStyleOptions} from 'pixi.js';

export const gameNameTextStyle: TextStyleOptions = {
    fontFamily: 'Poppins SemiBold',
    fontSize: 20,
    fill: '#FFCC00',
    align: 'left',
};

@injectFromBase()
export class GameHUDView extends HUDView {
    public static readonly MENU_BUTTON_CLICKED: string = 'MenuButtonView::BUTTON_CLICKED';
    private static readonly GAMENAME: string = 'Cyberchicken';

    protected _menuButton: GenericButton;
    protected _stepsCounter: ISpineAnimation;
    protected _currentStepNumber: AtlasNumbers;
    protected _nextStepNumber: AtlasNumbers;

    protected _currentValue: number;

    public async setNewStepNumber(value: number, total: number = 20): Promise<void> {
        this._stepsCounter.play('NUMBER_CHANGE', 0, false, 'IDLE');
        this._nextStepNumber.showNumber(`${value}/${total}`);
        await this._stepsCounter.getPromise(0);
        this._currentValue = value;
        this._currentStepNumber.showNumber(`${value}/${total}`);
    }

    protected setupButtons(): void {
        super.setupButtons();

        this._menuButton = new GenericButton('MENU_BUTTON.json', undefined, this.spineUtils, this.onMenuButtonClicked.bind(this));
        this.spineUtils.replaceSlotAttachment(this._footer, 'MENU_BUTTON', this._menuButton.button);

        this._stepsCounter = this.spineUtils.startSpineAnimationCreation('STEP_NUMBER.json', 'IDLE', true)
            .createAndStart();
        this.spineUtils.replaceSlotAttachment(this._header, 'STEP_NUMBER', this._stepsCounter.spine);

        this._currentStepNumber = new AtlasNumbers(this.assets, 'COINS_');
        this._currentStepNumber.showNumber('0123');
        this.spineUtils.replaceSlotAttachment(this._stepsCounter, 'SYMBOL_NUMBER', this._currentStepNumber);
        this._nextStepNumber = new AtlasNumbers(this.assets, 'COINS_');
        this._nextStepNumber.showNumber('3210');
        this.spineUtils.replaceSlotAttachment(this._stepsCounter, 'SYMBOL_NUMBER_NEW', this._nextStepNumber);
    }


    protected setupGameObjects(): void {
        super.setupGameObjects();

        const gameName: Text = new Text({text: GameHUDView.GAMENAME, style: gameNameTextStyle});
        this.spineUtils.replaceSlotAttachment(this._header, 'GAME_NAME_TXT', gameName);

    }

    protected onMenuButtonClicked(): void {
        this.emit(GameHUDView.MENU_BUTTON_CLICKED);
    }

}