import {
    BasicView,
    HALF_SCREEN_HEIGHT,
    HALF_SCREEN_WIDTH,
    SCREEN_HEIGHT,
    SCREEN_WIDTH, Timer
} from "@silverfoxgames/slotcore";
import {injectFromBase} from "inversify";
import {Container, Graphics, Text} from "pixi.js";

@injectFromBase()
export class LosePresentationView extends BasicView {

    public static readonly LOSE_PRESENTATION_FINISHED: string = 'LosePresentationView::LOSE_PRESENTATION_FINISHED';

    protected _currentTimer: Timer;

    public showPresentation(): void {
        const parentContainer: Container = new Container();

        const back = new Graphics()
            .rect(-HALF_SCREEN_WIDTH, -HALF_SCREEN_HEIGHT, SCREEN_WIDTH, SCREEN_HEIGHT)
            .fill({color: 0x000000, alpha: 0.5});
        parentContainer.addChild(back);
        parentContainer.interactive = true;

        const text = new Text({text: 'YOU LOSE\nClick to continue'});
        text.anchor.set(0.5);
        parentContainer.addChild(text);

        parentContainer.on('tap', this.hidePresentation.bind(this));
        parentContainer.on('click', this.hidePresentation.bind(this));

        this._currentTimer = this.timeUtils.createTimer(() => {
            this.hidePresentation();
        }, 1000);

        this.container.addChild(parentContainer);
    }

    public hidePresentation(): void {
        this._currentTimer.stop();
        this.container.removeChildren();
        this.emit(LosePresentationView.LOSE_PRESENTATION_FINISHED);
    }
}