import {GlobalStateIdle} from 'src/modules/globalstate/states/GlobalStateIdle';
import {GlobalStateStep} from 'src/modules/globalstate/states/GlobalStateStep';
import {GlobalStateWin} from 'src/modules/globalstate/states/GlobalStateWin';
import {GlobalStateInit} from 'src/modules/globalstate/states/GlobalStateInit';
import {GlobalStateModule} from '@silverfoxgames/slotcore';
import {injectFromBase} from 'inversify';
import {GlobalStateStepIdle} from 'src/modules/globalstate/states/GlobalStateStepIdle';
import {GameSpecificData} from 'src/gamedata/GameSpecificData';
import {GlobalStateLose} from 'src/modules/globalstate/states/GlobalStateLose';

@injectFromBase()
export class GlobalStateSpinModule extends GlobalStateModule<GameSpecificData> {

	public static readonly INIT: string = 'GlobalStateModule::INIT';
	public static readonly IDLE: string = 'GlobalStateModule::IDLE';
	public static readonly STEP: string = 'GlobalStateModule::STEP';
	public static readonly STEP_IDLE: string = 'GlobalStateModule::STEP_IDLE';
	public static readonly WIN: string = 'GlobalStateModule::WIN';
	public static readonly LOSE: string = 'GlobalStateModule::LOSE';

	public onStateHandle(event: string): void {
		this.onCurrentStateHandle(event);
	}

	protected enterFirstState(): void {
		this.gotoState(GlobalStateSpinModule.INIT);
	}

	protected setupStates(): void {
		super.setupStates();

		this.addState(new GlobalStateInit(this, GlobalStateSpinModule.INIT, this.eventManager));
		this.addState(new GlobalStateIdle(this, GlobalStateSpinModule.IDLE, this.eventManager));
		this.addState(new GlobalStateStep(this, GlobalStateSpinModule.STEP, this.eventManager));
		this.addState(new GlobalStateStepIdle(this, GlobalStateSpinModule.STEP_IDLE, this.eventManager));
		this.addState(new GlobalStateWin(this, GlobalStateSpinModule.WIN, this.eventManager));
		this.addState(new GlobalStateLose(this, GlobalStateSpinModule.LOSE, this.eventManager));
	}

}
