import {GlobalStateSpinModule} from 'src/modules/globalstate/GlobalStateSpinModule';
import {GlobalModuleState, IEventManager} from '@silverfoxgames/slotcore';
import {ChickenModule} from 'src/modules/chicken/ChickenModule';
import {RoadModule} from 'src/modules/road/RoadModule';
import {RoadEvents} from 'src/modules/road/RoadEvents';
import {CashoutButtonModule} from 'src/modules/movingUI/cashout/CashoutButtonModule';
import {ChickenKeypadController} from 'src/keypadController/ChickenKeypadController';
import {GoButtonModule} from 'src/modules/movingUI/go/GoButtonModule';
import {GameHUDModule} from 'src/hud/GameHUDModule';
import {ChickenGameController} from 'src/ChickenGameController';
import {GameBasicResponse} from 'src/gamedata/GameSpecificData';

export class GlobalStateStep extends GlobalModuleState<GlobalStateSpinModule> {

	protected _hudModule!: GameHUDModule;
	protected _spinButtonModule!: CashoutButtonModule;
	protected _keypadController!: ChickenKeypadController;
	protected _chickenModule!: ChickenModule;
	protected _roadModule!: RoadModule;
	protected _goButtonModule!: GoButtonModule;
	protected _cashoutButtonModule!: CashoutButtonModule;

	constructor(module: GlobalStateSpinModule, name: string, eventManager: IEventManager) {
		super(module, name, eventManager);

		this._hudModule = module.diContainer.get(GameHUDModule);
		this._spinButtonModule = module.diContainer.get(CashoutButtonModule);
		this._keypadController = module.diContainer.get(ChickenKeypadController);
		this._chickenModule = module.diContainer.get(ChickenModule);
		this._roadModule = module.diContainer.get(RoadModule);
		this._goButtonModule = module.diContainer.get(GoButtonModule);
		this._cashoutButtonModule = module.diContainer.get(CashoutButtonModule);
	}

	public async onEnterState(): Promise<void> {
		this._keypadController.disableOnRoundStarted();
		this._keypadController.disableOnStepStarted();
		this._cashoutButtonModule.hideButton();
		this._chickenModule.hideCurrentMultiplier();

		this.gameData.spinStartCleanup();

		this._roadModule.makeStep();

		if (this.gameData.currentStep === -1) {
			await this.chickenGameController.roundStart((result: GameBasicResponse) => {
				this.gameData.reactOnStep(result);
				this.handleFirstStep();
			}, this.gameData.getTotalBet(), this.gameData.currentGameMode);

			this._chickenModule.makeFirstStep();
		} else {
			await this.chickenGameController.step((result: GameBasicResponse) => {
				// TODO check why result behaves so strange!!!
				result.currentStep = (result as any).result.currentStep;
				result.isDead = (result as any).result.isDead;
				this.gameData.reactOnStep(result);
			});
			this._chickenModule.makeStep();
		}

		this._chickenModule.showMultiplier(this.gameData.multipliers[this.gameData.currentGameMode][this.gameData.currentStep]);
		this._hudModule.setNewCounterNumber(this.gameData.currentStep + 1);

		if (this.gameData.isDead) {
			await this.playFatalCarSequence();
			this._roadModule.resetRound();
			this._chickenModule.resetRound();
			this.gameData.resetSteps();
			this.module.gotoState(GlobalStateSpinModule.LOSE);
			return ;
		} else if (this.gameData.hasReachedFinalPosition()) {
			this._roadModule.spawnWinBarrier(this.gameData.currentStep)
			this.module.gotoState(GlobalStateSpinModule.WIN);
			return ;
		} else {
			this._roadModule.spawnWinBarrier(this.gameData.currentStep)
		}

		await this.timeUtils.wait(500);
		this.module.gotoState(GlobalStateSpinModule.STEP_IDLE);

	}

	public async playFatalCarSequence(): Promise<void> {
		this._roadModule.spawnLoseBarrier(this.gameData.currentStep)
		this._roadModule.spawnFatalCar(this.gameData.currentStep);
		await this.queueEvents.getEventPromise(RoadEvents.FATAL_CAR_REACHED_CHICKEN);
		this._chickenModule.hideCurrentMultiplier();
		await this._chickenModule.playDead();
		this._goButtonModule.resetGame();

		//TODO: add showing fatal screen
	}

	public onLeaveState(): void {
	}

	protected setupEvents(): void {
	}

	protected handleFirstStep(): void {
		this._hudModule.clearWin();
		this._hudModule.updateBalance();
	}

	protected onSpinButtonPressed(): void {
		this.module.gotoState(GlobalStateSpinModule.STEP);
	}

	public get chickenGameController(): ChickenGameController {
		return this.gameController as ChickenGameController;
	}

}
